import codecs, io, json, sys, unicodedata
assert sys.version_info[:3] == (3, 14, 7)
assert unicodedata.unidata_version == '16.0.0'
assert sys.platform == 'darwin' and sys.byteorder == 'little'
original = codecs.lookup_error('strict')
retained = []
def capture(value, errors):
    retained.append(errors)
    return value, 0
codecs.register(lambda name: (capture, capture, None, None) if name == 'newline_storage' else None)
class Name(str):
    pass
rows = []
for lead in (0xc2, 0xc4, 0xf0):
    for replacement in ('', '8', '88', '8\r', '\r', '\r\n', '8\r8', '8\r\n8', '8\n8', '\n8', '\u010d8', '\ud8008'):
        def recover(error):
            return (bytes([lead]) if isinstance(error, UnicodeEncodeError) else replacement, error.end)
        codecs.register_error('strict', recover)
        codecs.encode('', 'newline_storage', Name('\ud801'))
        text = retained[-1]
        codecs.register_error('strict', original)
        for translate in (False, True):
            for pending in (False, True):
                for final in (False, True):
                    decoder = io.IncrementalNewlineDecoder(None, translate)
                    decoder.setstate((b'', int(pending)))
                    result = decoder.decode(text, final)
                    ordinary = ''.join(chr(ord(c)) for c in result)
                    rows.append(dict(lead=lead, replacement=list(map(ord,replacement)), translate=translate, pending=pending, final=final, input_ascii=text.isascii(), input_equal=text==replacement, output=list(map(ord,result)), ascii=result.isascii(), equal=result==ordinary, reuse=result is text, state=decoder.getstate()[1], newlines=decoder.newlines))
print(json.dumps(dict(target=dict(version=sys.version, unicode=unicodedata.unidata_version, platform=sys.platform, byteorder=sys.byteorder), rows=rows)))
